/** Deterministic summary of the import (used by the audit doc + tests). */
export function summarizeLaunchImport(map: ResourceLaunchImportRecord[] = RESOURCE_LAUNCH_IMPORT) {
  const by = (k: (r: ResourceLaunchImportRecord) => string) =>
    map.reduce<Record<string, number>>((a, r) => { const v = k(r); a[v] = (a[v] ?? 0) + 1; return a }, {})
  return {
    total: map.length,
    dispositions: by(r => r.disposition),
    publicationStatuses: by(r => r.publicationStatus),
    verificationStatuses: by(r => r.verificationStatus),
    approvedForPublication: map.filter(r => r.publicationStatus === 'approved_for_publication').length,
    publicEligible: map.filter(r => r.publicationStatus === 'public_eligible' || r.publicationStatus === 'approved_for_publication').length,
    pendingVerification: map.filter(r => r.publicationStatus === 'held_for_review').length,
    resolvedCanonicalIds: map.filter(r => r.canonicalResourceId).length,
  }
}
